### SQL de Base - LDD (Langage de Définition de Données)

CREATE DATABASE bd_est;
DROP DATABASE bd_est;
SHOW DATABASES;

### Exemples ALTER TABLE

ALTER TABLE etudiant ADD (note NUMBER(5));
ALTER TABLE etudiant MODIFY nom VARCHAR(50) NOT NULL;
ALTER TABLE etudiant DROP COLUMN nom;
RENAME Pilote TO Naviguant;

### Suppression de table

DROP TABLE Nom_de_la_table [CASCADE CONSTRAINTS][PURGE];
TRUNCATE TABLE Nom_de_la_table; -- Supprime les données, conserve la structure

### L'ordre SELECT - Projection

SELECT colonne1, colonne2 FROM table;
SELECT * FROM table;
Renommage avec AS: SELECT Ville AS City FROM personne;
DISTINCT pour éliminer les doublons.

### L'ordre SELECT - Expressions et fonctions

Colonnes calculées: SELECT Prix, (Prix / 6.5596) AS Prix_Euros FROM vente;
Fonctions: UPPER(), AVG(), COUNT(*), SUM(), MIN(), MAX().

### Requêtes multi-tables - Jointure interne (INNER JOIN)

SELECT v.Marque, ve.Prix FROM voiture v JOIN vente ve ON v.NumVoit=ve.NumVoit;
Jointure sur plus de deux tables possible.

### Création des tables

CREATE TABLE Personne (NumAch NUMBER(10) PRIMARY KEY, Nom VARCHAR2(50) NOT NULL, Age NUMBER(3) NOT NULL, Ville VARCHAR2(50) NOT NULL, Sexe CHAR(1) NOT NULL, CONSTRAINT chk_age CHECK (Age BETWEEN 0 AND 120), CONSTRAINT chk_sexe CHECK (Sexe IN ('M','F')));
CREATE TABLE Voiture (NumVoit NUMBER(10) PRIMARY KEY, Marque VARCHAR2(50) NOT NULL, Type VARCHAR2(50) NOT NULL, Couleur VARCHAR2(20) NOT NULL);
CREATE TABLE Vente (DateVente DATE NOT NULL, Prix NUMBER(10) NOT NULL, NumVoit NUMBER(10) NOT NULL, NumAch NUMBER(10) NOT NULL, CONSTRAINT pk_vente PRIMARY KEY (NumVoit, NumAch), CONSTRAINT fk_vente_voiture FOREIGN KEY (NumVoit) REFERENCES Voiture(NumVoit), CONSTRAINT fk_vente_personne FOREIGN KEY (NumAch) REFERENCES Personne(NumAch));

